// 300 versículos para memorizar — texto Reina-Valera 1960, tomado tal cual (sin modificar).
// Categorías: consuelo, esperanza, gozo, ensenanza, jesus. Se priorizan los usados en la iglesia adventista
// (sábado, segunda venida, resurrección, salud, profecía, los tres ángeles).
window.DATOS_VERSICULOS = {
  categorias: [
    { id: 'todas', nombre: 'Todos', icono: '📖' },
    { id: 'consuelo', nombre: 'Consuelo en la tristeza', icono: '🤗' },
    { id: 'esperanza', nombre: 'Esperanza', icono: '🌅' },
    { id: 'gozo', nombre: 'Gozo y alabanza', icono: '😊' },
    { id: 'ensenanza', nombre: 'Enseñanzas', icono: '🎓' },
    { id: 'jesus', nombre: 'Palabras de Jesús', icono: '✝️' }
  ],
  versiculos: [
    {"id": 1, "cat": "consuelo", "cita": "Salmos 23:1", "libro": "Salmos", "texto": "Jehová es mi pastor; nada me faltará."},
    {"id": 2, "cat": "consuelo", "cita": "Salmos 23:4", "libro": "Salmos", "texto": "Aunque ande en valle de sombra de muerte, No temeré mal alguno, porque tú estarás conmigo; Tu vara y tu cayado me infundirán aliento."},
    {"id": 3, "cat": "consuelo", "cita": "Salmos 34:18", "libro": "Salmos", "texto": "Cercano está Jehová a los quebrantados de corazón; Y salva a los contritos de espíritu."},
    {"id": 4, "cat": "consuelo", "cita": "Salmos 46:1", "libro": "Salmos", "texto": "Dios es nuestro amparo y fortaleza, Nuestro pronto auxilio en las tribulaciones."},
    {"id": 5, "cat": "consuelo", "cita": "Salmos 55:22", "libro": "Salmos", "texto": "Echa sobre Jehová tu carga, y él te sustentará; No dejará para siempre caído al justo."},
    {"id": 6, "cat": "consuelo", "cita": "Salmos 147:3", "libro": "Salmos", "texto": "Él sana a los quebrantados de corazón, Y venda sus heridas."},
    {"id": 7, "cat": "consuelo", "cita": "Salmos 30:5", "libro": "Salmos", "texto": "Porque un momento será su ira, Pero su favor dura toda la vida. Por la noche durará el lloro, Y a la mañana vendrá la alegría."},
    {"id": 8, "cat": "consuelo", "cita": "Salmos 42:11", "libro": "Salmos", "texto": "¿Por qué te abates, oh alma mía, Y por qué te turbas dentro de mí? Espera en Dios; porque aún he de alabarle, Salvación mía y Dios mío."},
    {"id": 9, "cat": "consuelo", "cita": "Salmos 121:1-2", "libro": "Salmos", "texto": "Alzaré mis ojos a los montes; ¿De dónde vendrá mi socorro? Mi socorro viene de Jehová, Que hizo los cielos y la tierra."},
    {"id": 10, "cat": "consuelo", "cita": "Salmos 121:7", "libro": "Salmos", "texto": "Jehová te guardará de todo mal; Él guardará tu alma."},
    {"id": 11, "cat": "consuelo", "cita": "Salmos 91:1", "libro": "Salmos", "texto": "El que habita al abrigo del Altísimo Morará bajo la sombra del Omnipotente."},
    {"id": 12, "cat": "consuelo", "cita": "Salmos 91:11", "libro": "Salmos", "texto": "Pues a sus ángeles mandará acerca de ti, Que te guarden en todos tus caminos."},
    {"id": 13, "cat": "consuelo", "cita": "Salmos 27:1", "libro": "Salmos", "texto": "Jehová es mi luz y mi salvación; ¿de quién temeré? Jehová es la fortaleza de mi vida; ¿de quién he de atemorizarme?"},
    {"id": 14, "cat": "consuelo", "cita": "Salmos 27:10", "libro": "Salmos", "texto": "Aunque mi padre y mi madre me dejaran, Con todo, Jehová me recogerá."},
    {"id": 15, "cat": "consuelo", "cita": "Salmos 56:3", "libro": "Salmos", "texto": "En el día que temo, Yo en ti confío."},
    {"id": 16, "cat": "consuelo", "cita": "Salmos 61:2", "libro": "Salmos", "texto": "Desde el cabo de la tierra clamaré a ti, cuando mi corazón desmayare. Llévame a la roca que es más alta que yo,"},
    {"id": 17, "cat": "consuelo", "cita": "Salmos 62:8", "libro": "Salmos", "texto": "Esperad en él en todo tiempo, oh pueblos; Derramad delante de él vuestro corazón; Dios es nuestro refugio."},
    {"id": 18, "cat": "consuelo", "cita": "Salmos 73:26", "libro": "Salmos", "texto": "Mi carne y mi corazón desfallecen; Mas la roca de mi corazón y mi porción es Dios para siempre."},
    {"id": 19, "cat": "consuelo", "cita": "Salmos 94:19", "libro": "Salmos", "texto": "En la multitud de mis pensamientos dentro de mí, Tus consolaciones alegraban mi alma."},
    {"id": 20, "cat": "consuelo", "cita": "Salmos 126:5", "libro": "Salmos", "texto": "Los que sembraron con lágrimas, con regocijo segarán."},
    {"id": 21, "cat": "consuelo", "cita": "Salmos 4:8", "libro": "Salmos", "texto": "En paz me acostaré, y asimismo dormiré; Porque solo tú, Jehová, me haces vivir confiado."},
    {"id": 22, "cat": "consuelo", "cita": "Salmos 18:2", "libro": "Salmos", "texto": "Jehová, roca mía y castillo mío, y mi libertador; Dios mío, fortaleza mía, en él confiaré; Mi escudo, y la fuerza de mi salvación, mi alto refugio."},
    {"id": 23, "cat": "consuelo", "cita": "Salmos 34:4", "libro": "Salmos", "texto": "Busqué a Jehová, y él me oyó, Y me libró de todos mis temores."},
    {"id": 24, "cat": "consuelo", "cita": "Salmos 34:7", "libro": "Salmos", "texto": "El ángel de Jehová acampa alrededor de los que le temen, Y los defiende."},
    {"id": 25, "cat": "consuelo", "cita": "Salmos 37:5", "libro": "Salmos", "texto": "Encomienda a Jehová tu camino, Y confía en él; y él hará."},
    {"id": 26, "cat": "consuelo", "cita": "Salmos 46:10", "libro": "Salmos", "texto": "Estad quietos, y conoced que yo soy Dios; Seré exaltado entre las naciones; enaltecido seré en la tierra."},
    {"id": 27, "cat": "consuelo", "cita": "Salmos 50:15", "libro": "Salmos", "texto": "E invócame en el día de la angustia; Te libraré, y tú me honrarás."},
    {"id": 28, "cat": "consuelo", "cita": "Salmos 145:18", "libro": "Salmos", "texto": "Cercano está Jehová a todos los que le invocan, A todos los que le invocan de veras."},
    {"id": 29, "cat": "consuelo", "cita": "Salmos 103:13", "libro": "Salmos", "texto": "Como el padre se compadece de los hijos, Se compadece Jehová de los que le temen."},
    {"id": 30, "cat": "consuelo", "cita": "Isaías 41:10", "libro": "Isaías", "texto": "No temas, porque yo estoy contigo; no desmayes, porque yo soy tu Dios que te esfuerzo; siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia."},
    {"id": 31, "cat": "consuelo", "cita": "Isaías 41:13", "libro": "Isaías", "texto": "Porque yo Jehová soy tu Dios, quien te sostiene de tu mano derecha, y te dice: No temas, yo te ayudo."},
    {"id": 32, "cat": "consuelo", "cita": "Isaías 43:2", "libro": "Isaías", "texto": "Cuando pases por las aguas, yo estaré contigo; y si por los ríos, no te anegarán. Cuando pases por el fuego, no te quemarás, ni la llama arderá en ti."},
    {"id": 33, "cat": "consuelo", "cita": "Isaías 40:29", "libro": "Isaías", "texto": "Él da esfuerzo al cansado, y multiplica las fuerzas al que no tiene ningunas."},
    {"id": 34, "cat": "consuelo", "cita": "Isaías 26:3", "libro": "Isaías", "texto": "Tú guardarás en completa paz a aquel cuyo pensamiento en ti persevera; porque en ti ha confiado."},
    {"id": 35, "cat": "consuelo", "cita": "Isaías 49:15", "libro": "Isaías", "texto": "¿Se olvidará la mujer de lo que dio a luz, para dejar de compadecerse del hijo de su vientre? Aunque olvide ella, yo nunca me olvidaré de ti."},
    {"id": 36, "cat": "consuelo", "cita": "Isaías 54:10", "libro": "Isaías", "texto": "Porque los montes se moverán, y los collados temblarán, pero no se apartará de ti mi misericordia, ni el pacto de mi paz se quebrantará, dijo Jehová, el que tiene misericordia de ti."},
    {"id": 37, "cat": "consuelo", "cita": "Isaías 66:13", "libro": "Isaías", "texto": "Como aquel a quien consuela su madre, así os consolaré yo a vosotros, y en Jerusalén tomaréis consuelo."},
    {"id": 38, "cat": "consuelo", "cita": "Josué 1:9", "libro": "Josué", "texto": "Mira que te mando que te esfuerces y seas valiente; no temas ni desmayes, porque Jehová tu Dios estará contigo en dondequiera que vayas."},
    {"id": 39, "cat": "consuelo", "cita": "Deuteronomio 31:6", "libro": "Deuteronomio", "texto": "Esforzaos y cobrad ánimo; no temáis, ni tengáis miedo de ellos, porque Jehová tu Dios es el que va contigo; no te dejará, ni te desamparará."},
    {"id": 40, "cat": "consuelo", "cita": "Deuteronomio 31:8", "libro": "Deuteronomio", "texto": "Y Jehová va delante de ti; él estará contigo, no te dejará, ni te desamparará; no temas ni te intimides."},
    {"id": 41, "cat": "consuelo", "cita": "Deuteronomio 33:27", "libro": "Deuteronomio", "texto": "El eterno Dios es tu refugio, Y acá abajo los brazos eternos; Él echó de delante de ti al enemigo, Y dijo: Destruye."},
    {"id": 42, "cat": "consuelo", "cita": "Nahúm 1:7", "libro": "Nahúm", "texto": "Jehová es bueno, fortaleza en el día de la angustia; y conoce a los que en él confían."},
    {"id": 43, "cat": "consuelo", "cita": "Lamentaciones 3:22-23", "libro": "Lamentaciones", "texto": "Por la misericordia de Jehová no hemos sido consumidos, porque nunca decayeron sus misericordias. Nuevas son cada mañana; grande es tu fidelidad."},
    {"id": 44, "cat": "consuelo", "cita": "2 Corintios 1:3", "libro": "2 Corintios", "texto": "Bendito sea el Dios y Padre de nuestro Señor Jesucristo, Padre de misericordias y Dios de toda consolación,"},
    {"id": 45, "cat": "consuelo", "cita": "2 Corintios 12:9", "libro": "2 Corintios", "texto": "Y me ha dicho: Bástate mi gracia; porque mi poder se perfecciona en la debilidad. Por tanto, de buena gana me gloriaré más bien en mis debilidades, para que repose sobre mí el poder de Cristo."},
    {"id": 46, "cat": "consuelo", "cita": "2 Corintios 4:17", "libro": "2 Corintios", "texto": "Porque esta leve tribulación momentánea produce en nosotros un cada vez más excelente y eterno peso de gloria;"},
    {"id": 47, "cat": "consuelo", "cita": "Romanos 8:28", "libro": "Romanos", "texto": "Y sabemos que a los que aman a Dios, todas las cosas les ayudan a bien, esto es, a los que conforme a su propósito son llamados."},
    {"id": 48, "cat": "consuelo", "cita": "Filipenses 4:6", "libro": "Filipenses", "texto": "Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias."},
    {"id": 49, "cat": "consuelo", "cita": "1 Pedro 5:7", "libro": "1 Pedro", "texto": "echando toda vuestra ansiedad sobre él, porque él tiene cuidado de vosotros."},
    {"id": 50, "cat": "consuelo", "cita": "Hebreos 13:5", "libro": "Hebreos", "texto": "Sean vuestras costumbres sin avaricia, contentos con lo que tenéis ahora; porque él dijo: No te desampararé, ni te dejaré;"},
    {"id": 51, "cat": "consuelo", "cita": "Hebreos 4:16", "libro": "Hebreos", "texto": "Acerquémonos, pues, confiadamente al trono de la gracia, para alcanzar misericordia y hallar gracia para el oportuno socorro."},
    {"id": 52, "cat": "consuelo", "cita": "Sofonías 3:17", "libro": "Sofonías", "texto": "Jehová está en medio de ti, poderoso, él salvará; se gozará sobre ti con alegría, callará de amor, se regocijará sobre ti con cánticos."},
    {"id": 53, "cat": "consuelo", "cita": "Éxodo 14:14", "libro": "Éxodo", "texto": "Jehová peleará por vosotros, y vosotros estaréis tranquilos."},
    {"id": 54, "cat": "consuelo", "cita": "2 Timoteo 1:7", "libro": "2 Timoteo", "texto": "Porque no nos ha dado Dios espíritu de cobardía, sino de poder, de amor y de dominio propio."},
    {"id": 55, "cat": "consuelo", "cita": "Salmos 32:8", "libro": "Salmos", "texto": "Te haré entender, y te enseñaré el camino en que debes andar; Sobre ti fijaré mis ojos."},
    {"id": 56, "cat": "consuelo", "cita": "Isaías 43:1", "libro": "Isaías", "texto": "Ahora, así dice Jehová, Creador tuyo, oh Jacob, y Formador tuyo, oh Israel: No temas, porque yo te redimí; te puse nombre, mío eres tú."},
    {"id": 57, "cat": "consuelo", "cita": "Salmos 28:7", "libro": "Salmos", "texto": "Jehová es mi fortaleza y mi escudo; En él confió mi corazón, y fui ayudado, Por lo que se gozó mi corazón, Y con mi cántico le alabaré."},
    {"id": 58, "cat": "consuelo", "cita": "Salmos 3:3", "libro": "Salmos", "texto": "Mas tú, Jehová, eres escudo alrededor de mí; Mi gloria, y el que levanta mi cabeza."},
    {"id": 59, "cat": "esperanza", "cita": "Jeremías 29:11", "libro": "Jeremías", "texto": "Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis."},
    {"id": 60, "cat": "esperanza", "cita": "Isaías 40:31", "libro": "Isaías", "texto": "pero los que esperan a Jehová tendrán nuevas fuerzas; levantarán alas como las águilas; correrán, y no se cansarán; caminarán, y no se fatigarán."},
    {"id": 61, "cat": "esperanza", "cita": "Romanos 15:13", "libro": "Romanos", "texto": "Y el Dios de esperanza os llene de todo gozo y paz en el creer, para que abundéis en esperanza por el poder del Espíritu Santo."},
    {"id": 62, "cat": "esperanza", "cita": "Romanos 5:5", "libro": "Romanos", "texto": "y la esperanza no avergüenza; porque el amor de Dios ha sido derramado en nuestros corazones por el Espíritu Santo que nos fue dado."},
    {"id": 63, "cat": "esperanza", "cita": "Romanos 8:18", "libro": "Romanos", "texto": "Pues tengo por cierto que las aflicciones del tiempo presente no son comparables con la gloria venidera que en nosotros ha de manifestarse."},
    {"id": 64, "cat": "esperanza", "cita": "Romanos 12:12", "libro": "Romanos", "texto": "gozosos en la esperanza; sufridos en la tribulación; constantes en la oración;"},
    {"id": 65, "cat": "esperanza", "cita": "Hebreos 11:1", "libro": "Hebreos", "texto": "Es, pues, la fe la certeza de lo que se espera, la convicción de lo que no se ve."},
    {"id": 66, "cat": "esperanza", "cita": "Hebreos 10:23", "libro": "Hebreos", "texto": "Mantengamos firme, sin fluctuar, la profesión de nuestra esperanza, porque fiel es el que prometió."},
    {"id": 67, "cat": "esperanza", "cita": "Hebreos 6:19", "libro": "Hebreos", "texto": "La cual tenemos como segura y firme ancla del alma, y que penetra hasta dentro del velo,"},
    {"id": 68, "cat": "esperanza", "cita": "Hebreos 9:28", "libro": "Hebreos", "texto": "así también Cristo fue ofrecido una sola vez para llevar los pecados de muchos; y aparecerá por segunda vez, sin relación con el pecado, para salvar a los que le esperan."},
    {"id": 69, "cat": "esperanza", "cita": "1 Pedro 1:3", "libro": "1 Pedro", "texto": "Bendito el Dios y Padre de nuestro Señor Jesucristo, que según su grande misericordia nos hizo renacer para una esperanza viva, por la resurrección de Jesucristo de los muertos,"},
    {"id": 70, "cat": "esperanza", "cita": "Lamentaciones 3:25", "libro": "Lamentaciones", "texto": "Bueno es Jehová a los que en él esperan, al alma que le busca."},
    {"id": 71, "cat": "esperanza", "cita": "Lamentaciones 3:26", "libro": "Lamentaciones", "texto": "Bueno es esperar en silencio la salvación de Jehová."},
    {"id": 72, "cat": "esperanza", "cita": "Salmos 39:7", "libro": "Salmos", "texto": "Y ahora, Señor, ¿qué esperaré? Mi esperanza está en ti."},
    {"id": 73, "cat": "esperanza", "cita": "Salmos 130:5", "libro": "Salmos", "texto": "Esperé yo a Jehová, esperó mi alma; En su palabra he esperado."},
    {"id": 74, "cat": "esperanza", "cita": "Proverbios 23:18", "libro": "Proverbios", "texto": "Porque ciertamente hay fin, Y tu esperanza no será cortada."},
    {"id": 75, "cat": "esperanza", "cita": "Tito 2:13", "libro": "Tito", "texto": "aguardando la esperanza bienaventurada y la manifestación gloriosa de nuestro gran Dios y Salvador Jesucristo,"},
    {"id": 76, "cat": "esperanza", "cita": "Hechos 1:11", "libro": "Hechos", "texto": "los cuales también les dijeron: Varones galileos, ¿por qué estáis mirando al cielo? Este mismo Jesús, que ha sido tomado de vosotros al cielo, así vendrá como le habéis visto ir al cielo."},
    {"id": 77, "cat": "esperanza", "cita": "1 Tesalonicenses 4:16", "libro": "1 Tesalonicenses", "texto": "Porque el Señor mismo con voz de mando, con voz de arcángel, y con trompeta de Dios, descenderá del cielo; y los muertos en Cristo resucitarán primero."},
    {"id": 78, "cat": "esperanza", "cita": "1 Tesalonicenses 4:13", "libro": "1 Tesalonicenses", "texto": "Tampoco queremos, hermanos, que ignoréis acerca de los que duermen, para que no os entristezcáis como los otros que no tienen esperanza."},
    {"id": 79, "cat": "esperanza", "cita": "1 Corintios 15:52", "libro": "1 Corintios", "texto": "en un momento, en un abrir y cerrar de ojos, a la final trompeta; porque se tocará la trompeta, y los muertos serán resucitados incorruptibles, y nosotros seremos transformados."},
    {"id": 80, "cat": "esperanza", "cita": "1 Corintios 15:55", "libro": "1 Corintios", "texto": "¿Dónde está, oh muerte, tu aguijón? ¿Dónde, oh sepulcro, tu victoria?"},
    {"id": 81, "cat": "esperanza", "cita": "1 Corintios 2:9", "libro": "1 Corintios", "texto": "Antes bien, como está escrito: Cosas que ojo no vio, ni oído oyó, Ni han subido en corazón de hombre, Son las que Dios ha preparado para los que le aman."},
    {"id": 82, "cat": "esperanza", "cita": "Apocalipsis 21:4", "libro": "Apocalipsis", "texto": "Enjugará Dios toda lágrima de los ojos de ellos; y ya no habrá muerte, ni habrá más llanto, ni clamor, ni dolor; porque las primeras cosas pasaron."},
    {"id": 83, "cat": "esperanza", "cita": "Apocalipsis 21:1", "libro": "Apocalipsis", "texto": "Vi un cielo nuevo y una tierra nueva; porque el primer cielo y la primera tierra pasaron, y el mar ya no existía más."},
    {"id": 84, "cat": "esperanza", "cita": "Apocalipsis 21:5", "libro": "Apocalipsis", "texto": "Y el que estaba sentado en el trono dijo: He aquí, yo hago nuevas todas las cosas. Y me dijo: Escribe; porque estas palabras son fieles y verdaderas."},
    {"id": 85, "cat": "esperanza", "cita": "Apocalipsis 22:20", "libro": "Apocalipsis", "texto": "El que da testimonio de estas cosas dice: Ciertamente vengo en breve. Amén; sí, ven, Señor Jesús."},
    {"id": 86, "cat": "esperanza", "cita": "Apocalipsis 1:7", "libro": "Apocalipsis", "texto": "He aquí que viene con las nubes, y todo ojo le verá, y los que le traspasaron; y todos los linajes de la tierra harán lamentación por él. Sí, amén."},
    {"id": 87, "cat": "esperanza", "cita": "Apocalipsis 14:12", "libro": "Apocalipsis", "texto": "Aquí está la paciencia de los santos, los que guardan los mandamientos de Dios y la fe de Jesús."},
    {"id": 88, "cat": "esperanza", "cita": "Isaías 65:17", "libro": "Isaías", "texto": "Porque he aquí que yo crearé nuevos cielos y nueva tierra; y de lo primero no habrá memoria, ni más vendrá al pensamiento."},
    {"id": 89, "cat": "esperanza", "cita": "Isaías 65:25", "libro": "Isaías", "texto": "El lobo y el cordero serán apacentados juntos, y el león comerá paja como el buey; y el polvo será el alimento de la serpiente. No afligirán, ni harán mal en todo mi santo monte, dijo Jehová."},
    {"id": 90, "cat": "esperanza", "cita": "Daniel 12:2", "libro": "Daniel", "texto": "Y muchos de los que duermen en el polvo de la tierra serán despertados, unos para vida eterna, y otros para vergüenza y confusión perpetua."},
    {"id": 91, "cat": "esperanza", "cita": "Daniel 12:3", "libro": "Daniel", "texto": "Los entendidos resplandecerán como el resplandor del firmamento; y los que enseñan la justicia a la multitud, como las estrellas a perpetua eternidad."},
    {"id": 92, "cat": "esperanza", "cita": "Filipenses 3:20", "libro": "Filipenses", "texto": "Mas nuestra ciudadanía está en los cielos, de donde también esperamos al Salvador, al Señor Jesucristo;"},
    {"id": 93, "cat": "esperanza", "cita": "Filipenses 1:6", "libro": "Filipenses", "texto": "estando persuadido de esto, que el que comenzó en vosotros la buena obra, la perfeccionará hasta el día de Jesucristo;"},
    {"id": 94, "cat": "esperanza", "cita": "Colosenses 3:4", "libro": "Colosenses", "texto": "Cuando Cristo, vuestra vida, se manifieste, entonces vosotros también seréis manifestados con él en gloria."},
    {"id": 95, "cat": "esperanza", "cita": "1 Juan 3:2", "libro": "1 Juan", "texto": "Amados, ahora somos hijos de Dios, y aún no se ha manifestado lo que hemos de ser; pero sabemos que cuando él se manifieste, seremos semejantes a él, porque le veremos tal como él es."},
    {"id": 96, "cat": "esperanza", "cita": "2 Pedro 3:13", "libro": "2 Pedro", "texto": "Pero nosotros esperamos, según sus promesas, cielos nuevos y tierra nueva, en los cuales mora la justicia."},
    {"id": 97, "cat": "esperanza", "cita": "2 Pedro 3:9", "libro": "2 Pedro", "texto": "El Señor no retarda su promesa, según algunos la tienen por tardanza, sino que es paciente para con nosotros, no queriendo que ninguno perezca, sino que todos procedan al arrepentimiento."},
    {"id": 98, "cat": "esperanza", "cita": "Santiago 5:8", "libro": "Santiago", "texto": "Tened también vosotros paciencia, y afirmad vuestros corazones; porque la venida del Señor se acerca."},
    {"id": 99, "cat": "esperanza", "cita": "Job 19:25", "libro": "Job", "texto": "Yo sé que mi Redentor vive, Y al fin se levantará sobre el polvo;"},
    {"id": 100, "cat": "esperanza", "cita": "Isaías 25:8", "libro": "Isaías", "texto": "Destruirá a la muerte para siempre; y enjugará Jehová el Señor toda lágrima de todos los rostros; y quitará la afrenta de su pueblo de toda la tierra; porque Jehová lo ha dicho."},
    {"id": 101, "cat": "esperanza", "cita": "Isaías 25:9", "libro": "Isaías", "texto": "Y se dirá en aquel día: He aquí, este es nuestro Dios, le hemos esperado, y nos salvará; este es Jehová a quien hemos esperado, nos gozaremos y nos alegraremos en su salvación."},
    {"id": 102, "cat": "esperanza", "cita": "Miqueas 7:7", "libro": "Miqueas", "texto": "Mas yo a Jehová miraré, esperaré al Dios de mi salvación; el Dios mío me oirá."},
    {"id": 103, "cat": "esperanza", "cita": "Habacuc 2:3", "libro": "Habacuc", "texto": "Aunque la visión tardará aún por un tiempo, mas se apresura hacia el fin, y no mentirá; aunque tardare, espéralo, porque sin duda vendrá, no tardará."},
    {"id": 104, "cat": "esperanza", "cita": "Isaías 40:8", "libro": "Isaías", "texto": "Sécase la hierba, marchítase la flor; mas la palabra del Dios nuestro permanece para siempre."},
    {"id": 105, "cat": "esperanza", "cita": "Isaías 9:6", "libro": "Isaías", "texto": "Porque un niño nos es nacido, hijo nos es dado, y el principado sobre su hombro; y se llamará su nombre Admirable, Consejero, Dios Fuerte, Padre Eterno, Príncipe de Paz."},
    {"id": 106, "cat": "esperanza", "cita": "Malaquías 4:2", "libro": "Malaquías", "texto": "Mas a vosotros los que teméis mi nombre, nacerá el Sol de justicia, y en sus alas traerá salvación; y saldréis, y saltaréis como becerros de la manada."},
    {"id": 107, "cat": "esperanza", "cita": "Salmos 27:14", "libro": "Salmos", "texto": "Aguarda a Jehová; Esfuérzate, y aliéntese tu corazón; Sí, espera a Jehová."},
    {"id": 108, "cat": "esperanza", "cita": "Isaías 46:4", "libro": "Isaías", "texto": "Y hasta la vejez yo mismo, y hasta las canas os soportaré yo; yo hice, yo llevaré, yo soportaré y guardaré."},
    {"id": 109, "cat": "esperanza", "cita": "Efesios 3:20", "libro": "Efesios", "texto": "Y a Aquel que es poderoso para hacer todas las cosas mucho más abundantemente de lo que pedimos o entendemos, según el poder que actúa en nosotros,"},
    {"id": 110, "cat": "esperanza", "cita": "2 Corintios 4:16", "libro": "2 Corintios", "texto": "Por tanto, no desmayamos; antes aunque este nuestro hombre exterior se va desgastando, el interior no obstante se renueva de día en día."},
    {"id": 111, "cat": "esperanza", "cita": "Apocalipsis 22:5", "libro": "Apocalipsis", "texto": "No habrá allí más noche; y no tienen necesidad de luz de lámpara, ni de luz del sol, porque Dios el Señor los iluminará; y reinarán por los siglos de los siglos."},
    {"id": 112, "cat": "esperanza", "cita": "Isaías 53:5", "libro": "Isaías", "texto": "Mas él herido fue por nuestras rebeliones, molido por nuestros pecados; el castigo de nuestra paz fue sobre él, y por su llaga fuimos nosotros curados."},
    {"id": 113, "cat": "esperanza", "cita": "Salmos 31:24", "libro": "Salmos", "texto": "Esforzaos todos vosotros los que esperáis en Jehová, Y tome aliento vuestro corazón."},
    {"id": 114, "cat": "esperanza", "cita": "Romanos 6:23", "libro": "Romanos", "texto": "Porque la paga del pecado es muerte, mas la dádiva de Dios es vida eterna en Cristo Jesús Señor nuestro."},
    {"id": 115, "cat": "esperanza", "cita": "Isaías 35:4", "libro": "Isaías", "texto": "Decid a los de corazón apocado: Esforzaos, no temáis; he aquí que vuestro Dios viene con retribución, con pago; Dios mismo vendrá, y os salvará."},
    {"id": 116, "cat": "esperanza", "cita": "1 Juan 5:11-12", "libro": "1 Juan", "texto": "Y este es el testimonio: que Dios nos ha dado vida eterna; y esta vida está en su Hijo. El que tiene al Hijo, tiene la vida; el que no tiene al Hijo de Dios no tiene la vida."},
    {"id": 117, "cat": "gozo", "cita": "Salmos 47:1", "libro": "Salmos", "texto": "Pueblos todos, batid las manos; Aclamad a Dios con voz de júbilo."},
    {"id": 118, "cat": "gozo", "cita": "Salmos 118:24", "libro": "Salmos", "texto": "Este es el día que hizo Jehová; Nos gozaremos y alegraremos en él."},
    {"id": 119, "cat": "gozo", "cita": "Salmos 16:11", "libro": "Salmos", "texto": "Me mostrarás la senda de la vida; En tu presencia hay plenitud de gozo; Delicias a tu diestra para siempre."},
    {"id": 120, "cat": "gozo", "cita": "Salmos 100:1-2", "libro": "Salmos", "texto": "Cantad alegres a Dios, habitantes de toda la tierra. Servid a Jehová con alegría; Venid ante su presencia con regocijo."},
    {"id": 121, "cat": "gozo", "cita": "Salmos 100:4", "libro": "Salmos", "texto": "Entrad por sus puertas con acción de gracias, Por sus atrios con alabanza; Alabadle, bendecid su nombre."},
    {"id": 122, "cat": "gozo", "cita": "Salmos 100:5", "libro": "Salmos", "texto": "Porque Jehová es bueno; para siempre es su misericordia, Y su verdad por todas las generaciones."},
    {"id": 123, "cat": "gozo", "cita": "Salmos 150:6", "libro": "Salmos", "texto": "Todo lo que respira alabe a JAH. Aleluya."},
    {"id": 124, "cat": "gozo", "cita": "Salmos 103:1-2", "libro": "Salmos", "texto": "Bendice, alma mía, a Jehová, Y bendiga todo mi ser su santo nombre. Bendice, alma mía, a Jehová, Y no olvides ninguno de sus beneficios."},
    {"id": 125, "cat": "gozo", "cita": "Salmos 126:3", "libro": "Salmos", "texto": "Grandes cosas ha hecho Jehová con nosotros; Estaremos alegres."},
    {"id": 126, "cat": "gozo", "cita": "Salmos 30:11", "libro": "Salmos", "texto": "Has cambiado mi lamento en baile; Desataste mi cilicio, y me ceñiste de alegría."},
    {"id": 127, "cat": "gozo", "cita": "Salmos 32:11", "libro": "Salmos", "texto": "Alegraos en Jehová y gozaos, justos; Y cantad con júbilo todos vosotros los rectos de corazón."},
    {"id": 128, "cat": "gozo", "cita": "Salmos 34:1", "libro": "Salmos", "texto": "Bendeciré a Jehová en todo tiempo; Su alabanza estará de continuo en mi boca."},
    {"id": 129, "cat": "gozo", "cita": "Salmos 34:8", "libro": "Salmos", "texto": "Gustad, y ved que es bueno Jehová; Dichoso el hombre que confía en él."},
    {"id": 130, "cat": "gozo", "cita": "Salmos 37:4", "libro": "Salmos", "texto": "Deléitate asimismo en Jehová, Y él te concederá las peticiones de tu corazón."},
    {"id": 131, "cat": "gozo", "cita": "Salmos 40:3", "libro": "Salmos", "texto": "Puso luego en mi boca cántico nuevo, alabanza a nuestro Dios. Verán esto muchos, y temerán, Y confiarán en Jehová."},
    {"id": 132, "cat": "gozo", "cita": "Salmos 51:12", "libro": "Salmos", "texto": "Vuélveme el gozo de tu salvación, Y espíritu noble me sustente."},
    {"id": 133, "cat": "gozo", "cita": "Salmos 95:1", "libro": "Salmos", "texto": "Venid, aclamemos alegremente a Jehová; Cantemos con júbilo a la roca de nuestra salvación."},
    {"id": 134, "cat": "gozo", "cita": "Salmos 96:1", "libro": "Salmos", "texto": "Cantad a Jehová cántico nuevo; Cantad a Jehová, toda la tierra."},
    {"id": 135, "cat": "gozo", "cita": "Salmos 98:4", "libro": "Salmos", "texto": "Cantad alegres a Jehová, toda la tierra; Levantad la voz, y aplaudid, y cantad salmos."},
    {"id": 136, "cat": "gozo", "cita": "Salmos 107:1", "libro": "Salmos", "texto": "Alabad a Jehová, porque él es bueno; Porque para siempre es su misericordia."},
    {"id": 137, "cat": "gozo", "cita": "Salmos 136:1", "libro": "Salmos", "texto": "Alabad a Jehová, porque él es bueno, Porque para siempre es su misericordia."},
    {"id": 138, "cat": "gozo", "cita": "Salmos 145:3", "libro": "Salmos", "texto": "Grande es Jehová, y digno de suprema alabanza; Y su grandeza es inescrutable."},
    {"id": 139, "cat": "gozo", "cita": "Salmos 146:2", "libro": "Salmos", "texto": "Alabaré a Jehová en mi vida; Cantaré salmos a mi Dios mientras viva."},
    {"id": 140, "cat": "gozo", "cita": "Salmos 5:11", "libro": "Salmos", "texto": "Pero alégrense todos los que en ti confían; Den voces de júbilo para siempre, porque tú los defiendes; En ti se regocijen los que aman tu nombre."},
    {"id": 141, "cat": "gozo", "cita": "Salmos 9:1", "libro": "Salmos", "texto": "Te alabaré, oh Jehová, con todo mi corazón; Contaré todas tus maravillas."},
    {"id": 142, "cat": "gozo", "cita": "Salmos 92:1", "libro": "Salmos", "texto": "Bueno es alabarte, oh Jehová, Y cantar salmos a tu nombre, oh Altísimo;"},
    {"id": 143, "cat": "gozo", "cita": "Salmos 113:3", "libro": "Salmos", "texto": "Desde el nacimiento del sol hasta donde se pone, Sea alabado el nombre de Jehová."},
    {"id": 144, "cat": "gozo", "cita": "Salmos 117:1-2", "libro": "Salmos", "texto": "Alabad a Jehová, naciones todas; Pueblos todos, alabadle. Porque ha engrandecido sobre nosotros su misericordia, Y la fidelidad de Jehová es para siempre. Aleluya."},
    {"id": 145, "cat": "gozo", "cita": "Salmos 19:1", "libro": "Salmos", "texto": "Los cielos cuentan la gloria de Dios, Y el firmamento anuncia la obra de sus manos."},
    {"id": 146, "cat": "gozo", "cita": "Salmos 8:1", "libro": "Salmos", "texto": "¡Oh Jehová, Señor nuestro, Cuán glorioso es tu nombre en toda la tierra! Has puesto tu gloria sobre los cielos;"},
    {"id": 147, "cat": "gozo", "cita": "Salmos 139:14", "libro": "Salmos", "texto": "Te alabaré; porque formidables, maravillosas son tus obras; Estoy maravillado, Y mi alma lo sabe muy bien."},
    {"id": 148, "cat": "gozo", "cita": "Salmos 63:3", "libro": "Salmos", "texto": "Porque mejor es tu misericordia que la vida; Mis labios te alabarán."},
    {"id": 149, "cat": "gozo", "cita": "Salmos 89:1", "libro": "Salmos", "texto": "Las misericordias de Jehová cantaré perpetuamente; De generación en generación haré notoria tu fidelidad con mi boca."},
    {"id": 150, "cat": "gozo", "cita": "Filipenses 4:4", "libro": "Filipenses", "texto": "Regocijaos en el Señor siempre. Otra vez digo: ¡Regocijaos!"},
    {"id": 151, "cat": "gozo", "cita": "1 Tesalonicenses 5:16-18", "libro": "1 Tesalonicenses", "texto": "Estad siempre gozosos. Orad sin cesar. Dad gracias en todo, porque esta es la voluntad de Dios para con vosotros en Cristo Jesús."},
    {"id": 152, "cat": "gozo", "cita": "Romanos 14:17", "libro": "Romanos", "texto": "porque el reino de Dios no es comida ni bebida, sino justicia, paz y gozo en el Espíritu Santo."},
    {"id": 153, "cat": "gozo", "cita": "Gálatas 5:22-23", "libro": "Gálatas", "texto": "Mas el fruto del Espíritu es amor, gozo, paz, paciencia, benignidad, bondad, fe, mansedumbre, templanza; contra tales cosas no hay ley."},
    {"id": 154, "cat": "gozo", "cita": "Proverbios 17:22", "libro": "Proverbios", "texto": "El corazón alegre constituye buen remedio; Mas el espíritu triste seca los huesos."},
    {"id": 155, "cat": "gozo", "cita": "Proverbios 15:13", "libro": "Proverbios", "texto": "El corazón alegre hermosea el rostro; Mas por el dolor del corazón el espíritu se abate."},
    {"id": 156, "cat": "gozo", "cita": "Isaías 61:10", "libro": "Isaías", "texto": "En gran manera me gozaré en Jehová, mi alma se alegrará en mi Dios; porque me vistió con vestiduras de salvación, me rodeó de manto de justicia, como a novio me atavió, y como a novia adornada con sus joyas."},
    {"id": 157, "cat": "gozo", "cita": "Isaías 12:2", "libro": "Isaías", "texto": "He aquí Dios es salvación mía; me aseguraré y no temeré; porque mi fortaleza y mi canción es JAH Jehová, quien ha sido salvación para mí."},
    {"id": 158, "cat": "gozo", "cita": "Isaías 55:12", "libro": "Isaías", "texto": "Porque con alegría saldréis, y con paz seréis vueltos; los montes y los collados levantarán canción delante de vosotros, y todos los árboles del campo darán palmadas de aplauso."},
    {"id": 159, "cat": "gozo", "cita": "Habacuc 3:18", "libro": "Habacuc", "texto": "Con todo, yo me alegraré en Jehová, Y me gozaré en el Dios de mi salvación."},
    {"id": 160, "cat": "gozo", "cita": "Lucas 2:10-11", "libro": "Lucas", "texto": "Pero el ángel les dijo: No temáis; porque he aquí os doy nuevas de gran gozo, que será para todo el pueblo: que os ha nacido hoy, en la ciudad de David, un Salvador, que es CRISTO el Señor."},
    {"id": 161, "cat": "gozo", "cita": "Santiago 1:2-3", "libro": "Santiago", "texto": "Hermanos míos, tened por sumo gozo cuando os halléis en diversas pruebas, sabiendo que la prueba de vuestra fe produce paciencia."},
    {"id": 162, "cat": "gozo", "cita": "1 Pedro 1:8", "libro": "1 Pedro", "texto": "a quien amáis sin haberle visto, en quien creyendo, aunque ahora no lo veáis, os alegráis con gozo inefable y glorioso;"},
    {"id": 163, "cat": "gozo", "cita": "Colosenses 3:16", "libro": "Colosenses", "texto": "La palabra de Cristo more en abundancia en vosotros, enseñándoos y exhortándoos unos a otros en toda sabiduría, cantando con gracia en vuestros corazones al Señor con salmos e himnos y cánticos espirituales."},
    {"id": 164, "cat": "gozo", "cita": "Colosenses 3:17", "libro": "Colosenses", "texto": "Y todo lo que hacéis, sea de palabra o de hecho, hacedlo todo en el nombre del Señor Jesús, dando gracias a Dios Padre por medio de él."},
    {"id": 165, "cat": "gozo", "cita": "Efesios 5:20", "libro": "Efesios", "texto": "dando siempre gracias por todo al Dios y Padre, en el nombre de nuestro Señor Jesucristo."},
    {"id": 166, "cat": "gozo", "cita": "Hebreos 13:15", "libro": "Hebreos", "texto": "Así que, ofrezcamos siempre a Dios, por medio de él, sacrificio de alabanza, es decir, fruto de labios que confiesan su nombre."},
    {"id": 167, "cat": "gozo", "cita": "1 Crónicas 16:34", "libro": "1 Crónicas", "texto": "Aclamad a Jehová, porque él es bueno; Porque su misericordia es eterna."},
    {"id": 168, "cat": "gozo", "cita": "Salmos 4:7", "libro": "Salmos", "texto": "Tú diste alegría a mi corazón Mayor que la de ellos cuando abundaba su grano y su mosto."},
    {"id": 169, "cat": "gozo", "cita": "Salmos 33:1", "libro": "Salmos", "texto": "Alegraos, oh justos, en Jehová; En los íntegros es hermosa la alabanza."},
    {"id": 170, "cat": "gozo", "cita": "Salmos 13:5", "libro": "Salmos", "texto": "Mas yo en tu misericordia he confiado; Mi corazón se alegrará en tu salvación."},
    {"id": 171, "cat": "ensenanza", "cita": "Proverbios 3:5-6", "libro": "Proverbios", "texto": "Fíate de Jehová de todo tu corazón, Y no te apoyes en tu propia prudencia. Reconócelo en todos tus caminos, Y él enderezará tus veredas."},
    {"id": 172, "cat": "ensenanza", "cita": "Proverbios 1:7", "libro": "Proverbios", "texto": "El principio de la sabiduría es el temor de Jehová; Los insensatos desprecian la sabiduría y la enseñanza."},
    {"id": 173, "cat": "ensenanza", "cita": "Proverbios 9:10", "libro": "Proverbios", "texto": "El temor de Jehová es el principio de la sabiduría, Y el conocimiento del Santísimo es la inteligencia."},
    {"id": 174, "cat": "ensenanza", "cita": "Proverbios 22:6", "libro": "Proverbios", "texto": "Instruye al niño en su camino, Y aun cuando fuere viejo no se apartará de él."},
    {"id": 175, "cat": "ensenanza", "cita": "Proverbios 15:1", "libro": "Proverbios", "texto": "La blanda respuesta quita la ira; Mas la palabra áspera hace subir el furor."},
    {"id": 176, "cat": "ensenanza", "cita": "Proverbios 16:3", "libro": "Proverbios", "texto": "Encomienda a Jehová tus obras, Y tus pensamientos serán afirmados."},
    {"id": 177, "cat": "ensenanza", "cita": "Proverbios 4:23", "libro": "Proverbios", "texto": "Sobre toda cosa guardada, guarda tu corazón; Porque de él mana la vida."},
    {"id": 178, "cat": "ensenanza", "cita": "Proverbios 12:22", "libro": "Proverbios", "texto": "Los labios mentirosos son abominación a Jehová; Pero los que hacen verdad son su contentamiento."},
    {"id": 179, "cat": "ensenanza", "cita": "Proverbios 14:12", "libro": "Proverbios", "texto": "Hay camino que al hombre le parece derecho; Pero su fin es camino de muerte."},
    {"id": 180, "cat": "ensenanza", "cita": "Proverbios 17:17", "libro": "Proverbios", "texto": "En todo tiempo ama el amigo, Y es como un hermano en tiempo de angustia."},
    {"id": 181, "cat": "ensenanza", "cita": "Proverbios 18:10", "libro": "Proverbios", "texto": "Torre fuerte es el nombre de Jehová; A él correrá el justo, y será levantado."},
    {"id": 182, "cat": "ensenanza", "cita": "Proverbios 20:1", "libro": "Proverbios", "texto": "El vino es escarnecedor, la sidra alborotadora, Y cualquiera que por ellos yerra no es sabio."},
    {"id": 183, "cat": "ensenanza", "cita": "Proverbios 28:13", "libro": "Proverbios", "texto": "El que encubre sus pecados no prosperará; Mas el que los confiesa y se aparta alcanzará misericordia."},
    {"id": 184, "cat": "ensenanza", "cita": "Eclesiastés 12:13", "libro": "Eclesiastés", "texto": "El fin de todo el discurso oído es este: Teme a Dios, y guarda sus mandamientos; porque esto es el todo del hombre."},
    {"id": 185, "cat": "ensenanza", "cita": "Eclesiastés 12:1", "libro": "Eclesiastés", "texto": "Acuérdate de tu Creador en los días de tu juventud, antes que vengan los días malos, y lleguen los años de los cuales digas: No tengo en ellos contentamiento;"},
    {"id": 186, "cat": "ensenanza", "cita": "Eclesiastés 3:1", "libro": "Eclesiastés", "texto": "Todo tiene su tiempo, y todo lo que se quiere debajo del cielo tiene su hora."},
    {"id": 187, "cat": "ensenanza", "cita": "Eclesiastés 9:5", "libro": "Eclesiastés", "texto": "Porque los que viven saben que han de morir; pero los muertos nada saben, ni tienen más paga; porque su memoria es puesta en olvido."},
    {"id": 188, "cat": "ensenanza", "cita": "Génesis 1:1", "libro": "Génesis", "texto": "En el principio creó Dios los cielos y la tierra."},
    {"id": 189, "cat": "ensenanza", "cita": "Génesis 1:27", "libro": "Génesis", "texto": "Y creó Dios al hombre a su imagen, a imagen de Dios lo creó; varón y hembra los creó."},
    {"id": 190, "cat": "ensenanza", "cita": "Génesis 2:3", "libro": "Génesis", "texto": "Y bendijo Dios al día séptimo, y lo santificó, porque en él reposó de toda la obra que había hecho en la creación."},
    {"id": 191, "cat": "ensenanza", "cita": "Éxodo 20:8", "libro": "Éxodo", "texto": "Acuérdate del día de reposo para santificarlo."},
    {"id": 192, "cat": "ensenanza", "cita": "Éxodo 20:11", "libro": "Éxodo", "texto": "Porque en seis días hizo Jehová los cielos y la tierra, el mar, y todas las cosas que en ellos hay, y reposó en el séptimo día; por tanto, Jehová bendijo el día de reposo y lo santificó."},
    {"id": 193, "cat": "ensenanza", "cita": "Ezequiel 20:12", "libro": "Ezequiel", "texto": "Y les di también mis días de reposo, para que fuesen por señal entre mí y ellos, para que supiesen que yo soy Jehová que los santifico."},
    {"id": 194, "cat": "ensenanza", "cita": "Ezequiel 20:20", "libro": "Ezequiel", "texto": "y santificad mis días de reposo, y sean por señal entre mí y vosotros, para que sepáis que yo soy Jehová vuestro Dios."},
    {"id": 195, "cat": "ensenanza", "cita": "Isaías 66:23", "libro": "Isaías", "texto": "Y de mes en mes, y de día de reposo en día de reposo, vendrán todos a adorar delante de mí, dijo Jehová."},
    {"id": 196, "cat": "ensenanza", "cita": "Lucas 4:16", "libro": "Lucas", "texto": "Vino a Nazaret, donde se había criado; y en el día de reposo entró en la sinagoga, conforme a su costumbre, y se levantó a leer."},
    {"id": 197, "cat": "ensenanza", "cita": "Hebreos 4:9", "libro": "Hebreos", "texto": "Por tanto, queda un reposo para el pueblo de Dios."},
    {"id": 198, "cat": "ensenanza", "cita": "1 Corintios 6:19", "libro": "1 Corintios", "texto": "¿O ignoráis que vuestro cuerpo es templo del Espíritu Santo, el cual está en vosotros, el cual tenéis de Dios, y que no sois vuestros?"},
    {"id": 199, "cat": "ensenanza", "cita": "1 Corintios 10:31", "libro": "1 Corintios", "texto": "Si, pues, coméis o bebéis, o hacéis otra cosa, hacedlo todo para la gloria de Dios."},
    {"id": 200, "cat": "ensenanza", "cita": "3 Juan 1:2", "libro": "3 Juan", "texto": "Amado, yo deseo que tú seas prosperado en todas las cosas, y que tengas salud, así como prospera tu alma."},
    {"id": 201, "cat": "ensenanza", "cita": "Daniel 1:8", "libro": "Daniel", "texto": "Y Daniel propuso en su corazón no contaminarse con la porción de la comida del rey, ni con el vino que él bebía; pidió, por tanto, al jefe de los eunucos que no se le obligase a contaminarse."},
    {"id": 202, "cat": "ensenanza", "cita": "Romanos 12:1", "libro": "Romanos", "texto": "Así que, hermanos, os ruego por las misericordias de Dios, que presentéis vuestros cuerpos en sacrificio vivo, santo, agradable a Dios, que es vuestro culto racional."},
    {"id": 203, "cat": "ensenanza", "cita": "Romanos 12:2", "libro": "Romanos", "texto": "No os conforméis a este siglo, sino transformaos por medio de la renovación de vuestro entendimiento, para que comprobéis cuál sea la buena voluntad de Dios, agradable y perfecta."},
    {"id": 204, "cat": "ensenanza", "cita": "Romanos 3:23", "libro": "Romanos", "texto": "por cuanto todos pecaron, y están destituidos de la gloria de Dios,"},
    {"id": 205, "cat": "ensenanza", "cita": "Romanos 10:17", "libro": "Romanos", "texto": "Así que la fe es por el oír, y el oír, por la palabra de Dios."},
    {"id": 206, "cat": "ensenanza", "cita": "Romanos 1:16", "libro": "Romanos", "texto": "Porque no me avergüenzo del evangelio, porque es poder de Dios para salvación a todo aquel que cree; al judío primeramente, y también al griego."},
    {"id": 207, "cat": "ensenanza", "cita": "Efesios 2:8", "libro": "Efesios", "texto": "Porque por gracia sois salvos por medio de la fe; y esto no de vosotros, pues es don de Dios;"},
    {"id": 208, "cat": "ensenanza", "cita": "Efesios 4:32", "libro": "Efesios", "texto": "Antes sed benignos unos con otros, misericordiosos, perdonándoos unos a otros, como Dios también os perdonó a vosotros en Cristo."},
    {"id": 209, "cat": "ensenanza", "cita": "Efesios 6:1", "libro": "Efesios", "texto": "Hijos, obedeced en el Señor a vuestros padres, porque esto es justo."},
    {"id": 210, "cat": "ensenanza", "cita": "Colosenses 3:20", "libro": "Colosenses", "texto": "Hijos, obedeced a vuestros padres en todo, porque esto agrada al Señor."},
    {"id": 211, "cat": "ensenanza", "cita": "Gálatas 6:7", "libro": "Gálatas", "texto": "No os engañéis; Dios no puede ser burlado: pues todo lo que el hombre sembrare, eso también segará."},
    {"id": 212, "cat": "ensenanza", "cita": "Hebreos 11:6", "libro": "Hebreos", "texto": "Pero sin fe es imposible agradar a Dios; porque es necesario que el que se acerca a Dios crea que le hay, y que es galardonador de los que le buscan."},
    {"id": 213, "cat": "ensenanza", "cita": "Santiago 1:5", "libro": "Santiago", "texto": "Y si alguno de vosotros tiene falta de sabiduría, pídala a Dios, el cual da a todos abundantemente y sin reproche, y le será dada."},
    {"id": 214, "cat": "ensenanza", "cita": "Santiago 1:22", "libro": "Santiago", "texto": "Pero sed hacedores de la palabra, y no tan solamente oidores, engañándoos a vosotros mismos."},
    {"id": 215, "cat": "ensenanza", "cita": "Santiago 4:7", "libro": "Santiago", "texto": "Someteos, pues, a Dios; resistid al diablo, y huirá de vosotros."},
    {"id": 216, "cat": "ensenanza", "cita": "1 Juan 1:9", "libro": "1 Juan", "texto": "Si confesamos nuestros pecados, él es fiel y justo para perdonar nuestros pecados, y limpiarnos de toda maldad."},
    {"id": 217, "cat": "ensenanza", "cita": "1 Juan 4:8", "libro": "1 Juan", "texto": "El que no ama, no ha conocido a Dios; porque Dios es amor."},
    {"id": 218, "cat": "ensenanza", "cita": "1 Juan 5:3", "libro": "1 Juan", "texto": "Pues este es el amor a Dios, que guardemos sus mandamientos; y sus mandamientos no son gravosos."},
    {"id": 219, "cat": "ensenanza", "cita": "2 Timoteo 3:16", "libro": "2 Timoteo", "texto": "Toda la Escritura es inspirada por Dios, y útil para enseñar, para redargüir, para corregir, para instruir en justicia,"},
    {"id": 220, "cat": "ensenanza", "cita": "Salmos 119:105", "libro": "Salmos", "texto": "Lámpara es a mis pies tu palabra, Y lumbrera a mi camino."},
    {"id": 221, "cat": "ensenanza", "cita": "Salmos 119:11", "libro": "Salmos", "texto": "En mi corazón he guardado tus dichos, Para no pecar contra ti."},
    {"id": 222, "cat": "ensenanza", "cita": "Salmos 51:10", "libro": "Salmos", "texto": "Crea en mí, oh Dios, un corazón limpio, Y renueva un espíritu recto dentro de mí."},
    {"id": 223, "cat": "ensenanza", "cita": "Miqueas 6:8", "libro": "Miqueas", "texto": "Oh hombre, él te ha declarado lo que es bueno, y qué pide Jehová de ti: solamente hacer justicia, y amar misericordia, y humillarte ante tu Dios."},
    {"id": 224, "cat": "ensenanza", "cita": "Isaías 8:20", "libro": "Isaías", "texto": "¡A la ley y al testimonio! Si no dijeren conforme a esto, es porque no les ha amanecido."},
    {"id": 225, "cat": "ensenanza", "cita": "Isaías 1:18", "libro": "Isaías", "texto": "Venid luego, dice Jehová, y estemos a cuenta: si vuestros pecados fueren como la grana, como la nieve serán emblanquecidos; si fueren rojos como el carmesí, vendrán a ser como blanca lana."},
    {"id": 226, "cat": "ensenanza", "cita": "2 Crónicas 7:14", "libro": "2 Crónicas", "texto": "si se humillare mi pueblo, sobre el cual mi nombre es invocado, y oraren, y buscaren mi rostro, y se convirtieren de sus malos caminos; entonces yo oiré desde los cielos, y perdonaré sus pecados, y sanaré su tierra."},
    {"id": 227, "cat": "ensenanza", "cita": "Amós 3:7", "libro": "Amós", "texto": "Porque no hará nada Jehová el Señor, sin que revele su secreto a sus siervos los profetas."},
    {"id": 228, "cat": "ensenanza", "cita": "Apocalipsis 12:17", "libro": "Apocalipsis", "texto": "Entonces el dragón se llenó de ira contra la mujer; y se fue a hacer guerra contra el resto de la descendencia de ella, los que guardan los mandamientos de Dios y tienen el testimonio de Jesucristo."},
    {"id": 229, "cat": "ensenanza", "cita": "Apocalipsis 14:7", "libro": "Apocalipsis", "texto": "diciendo a gran voz: Temed a Dios, y dadle gloria, porque la hora de su juicio ha llegado; y adorad a aquel que hizo el cielo y la tierra, el mar y las fuentes de las aguas."},
    {"id": 230, "cat": "ensenanza", "cita": "Hechos 5:29", "libro": "Hechos", "texto": "Respondiendo Pedro y los apóstoles, dijeron: Es necesario obedecer a Dios antes que a los hombres."},
    {"id": 231, "cat": "ensenanza", "cita": "Hechos 4:12", "libro": "Hechos", "texto": "Y en ningún otro hay salvación; porque no hay otro nombre bajo el cielo, dado a los hombres, en que podamos ser salvos."},
    {"id": 232, "cat": "ensenanza", "cita": "Hechos 16:31", "libro": "Hechos", "texto": "Ellos dijeron: Cree en el Señor Jesucristo, y serás salvo, tú y tu casa."},
    {"id": 233, "cat": "ensenanza", "cita": "Filipenses 4:13", "libro": "Filipenses", "texto": "Todo lo puedo en Cristo que me fortalece."},
    {"id": 234, "cat": "ensenanza", "cita": "1 Timoteo 4:12", "libro": "1 Timoteo", "texto": "Ninguno tenga en poco tu juventud, sino sé ejemplo de los creyentes en palabra, conducta, amor, espíritu, fe y pureza."},
    {"id": 235, "cat": "ensenanza", "cita": "Juan 1:1", "libro": "Juan", "texto": "En el principio era el Verbo, y el Verbo era con Dios, y el Verbo era Dios."},
    {"id": 236, "cat": "jesus", "cita": "Juan 3:16", "libro": "Juan", "texto": "Porque de tal manera amó Dios al mundo, que ha dado a su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna."},
    {"id": 237, "cat": "jesus", "cita": "Juan 14:6", "libro": "Juan", "texto": "Jesús le dijo: Yo soy el camino, y la verdad, y la vida; nadie viene al Padre, sino por mí."},
    {"id": 238, "cat": "jesus", "cita": "Juan 14:1", "libro": "Juan", "texto": "No se turbe vuestro corazón; creéis en Dios, creed también en mí."},
    {"id": 239, "cat": "jesus", "cita": "Juan 14:3", "libro": "Juan", "texto": "Y si me fuere y os preparare lugar, vendré otra vez, y os tomaré a mí mismo, para que donde yo estoy, vosotros también estéis."},
    {"id": 240, "cat": "jesus", "cita": "Juan 14:15", "libro": "Juan", "texto": "Si me amáis, guardad mis mandamientos."},
    {"id": 241, "cat": "jesus", "cita": "Juan 14:27", "libro": "Juan", "texto": "La paz os dejo, mi paz os doy; yo no os la doy como el mundo la da. No se turbe vuestro corazón, ni tenga miedo."},
    {"id": 242, "cat": "jesus", "cita": "Juan 16:33", "libro": "Juan", "texto": "Estas cosas os he hablado para que en mí tengáis paz. En el mundo tendréis aflicción; pero confiad, yo he vencido al mundo."},
    {"id": 243, "cat": "jesus", "cita": "Juan 8:12", "libro": "Juan", "texto": "Otra vez Jesús les habló, diciendo: Yo soy la luz del mundo; el que me sigue, no andará en tinieblas, sino que tendrá la luz de la vida."},
    {"id": 244, "cat": "jesus", "cita": "Juan 8:32", "libro": "Juan", "texto": "y conoceréis la verdad, y la verdad os hará libres."},
    {"id": 245, "cat": "jesus", "cita": "Juan 6:35", "libro": "Juan", "texto": "Jesús les dijo: Yo soy el pan de vida; el que a mí viene, nunca tendrá hambre; y el que en mí cree, no tendrá sed jamás."},
    {"id": 246, "cat": "jesus", "cita": "Juan 10:10", "libro": "Juan", "texto": "El ladrón no viene sino para hurtar y matar y destruir; yo he venido para que tengan vida, y para que la tengan en abundancia."},
    {"id": 247, "cat": "jesus", "cita": "Juan 10:11", "libro": "Juan", "texto": "Yo soy el buen pastor; el buen pastor su vida da por las ovejas."},
    {"id": 248, "cat": "jesus", "cita": "Juan 10:27", "libro": "Juan", "texto": "Mis ovejas oyen mi voz, y yo las conozco, y me siguen,"},
    {"id": 249, "cat": "jesus", "cita": "Juan 11:25", "libro": "Juan", "texto": "Le dijo Jesús: Yo soy la resurrección y la vida; el que cree en mí, aunque esté muerto, vivirá."},
    {"id": 250, "cat": "jesus", "cita": "Juan 13:34", "libro": "Juan", "texto": "Un mandamiento nuevo os doy: Que os améis unos a otros; como yo os he amado, que también os améis unos a otros."},
    {"id": 251, "cat": "jesus", "cita": "Juan 13:35", "libro": "Juan", "texto": "En esto conocerán todos que sois mis discípulos, si tuviereis amor los unos con los otros."},
    {"id": 252, "cat": "jesus", "cita": "Juan 15:5", "libro": "Juan", "texto": "Yo soy la vid, vosotros los pámpanos; el que permanece en mí, y yo en él, este lleva mucho fruto; porque separados de mí nada podéis hacer."},
    {"id": 253, "cat": "jesus", "cita": "Juan 15:12", "libro": "Juan", "texto": "Este es mi mandamiento: Que os améis unos a otros, como yo os he amado."},
    {"id": 254, "cat": "jesus", "cita": "Juan 15:13", "libro": "Juan", "texto": "Nadie tiene mayor amor que este, que uno ponga su vida por sus amigos."},
    {"id": 255, "cat": "jesus", "cita": "Juan 15:11", "libro": "Juan", "texto": "Estas cosas os he hablado, para que mi gozo esté en vosotros, y vuestro gozo sea cumplido."},
    {"id": 256, "cat": "jesus", "cita": "Juan 16:24", "libro": "Juan", "texto": "Hasta ahora nada habéis pedido en mi nombre; pedid, y recibiréis, para que vuestro gozo sea cumplido."},
    {"id": 257, "cat": "jesus", "cita": "Juan 5:39", "libro": "Juan", "texto": "Escudriñad las Escrituras; porque a vosotros os parece que en ellas tenéis la vida eterna; y ellas son las que dan testimonio de mí;"},
    {"id": 258, "cat": "jesus", "cita": "Juan 6:37", "libro": "Juan", "texto": "Todo lo que el Padre me da, vendrá a mí; y al que a mí viene, no le echo fuera."},
    {"id": 259, "cat": "jesus", "cita": "Juan 17:17", "libro": "Juan", "texto": "Santifícalos en tu verdad; tu palabra es verdad."},
    {"id": 260, "cat": "jesus", "cita": "Mateo 5:3", "libro": "Mateo", "texto": "Bienaventurados los pobres en espíritu, porque de ellos es el reino de los cielos."},
    {"id": 261, "cat": "jesus", "cita": "Mateo 5:4", "libro": "Mateo", "texto": "Bienaventurados los que lloran, porque ellos recibirán consolación."},
    {"id": 262, "cat": "jesus", "cita": "Mateo 5:5", "libro": "Mateo", "texto": "Bienaventurados los mansos, porque ellos recibirán la tierra por heredad."},
    {"id": 263, "cat": "jesus", "cita": "Mateo 5:6", "libro": "Mateo", "texto": "Bienaventurados los que tienen hambre y sed de justicia, porque ellos serán saciados."},
    {"id": 264, "cat": "jesus", "cita": "Mateo 5:7", "libro": "Mateo", "texto": "Bienaventurados los misericordiosos, porque ellos alcanzarán misericordia."},
    {"id": 265, "cat": "jesus", "cita": "Mateo 5:8", "libro": "Mateo", "texto": "Bienaventurados los de limpio corazón, porque ellos verán a Dios."},
    {"id": 266, "cat": "jesus", "cita": "Mateo 5:9", "libro": "Mateo", "texto": "Bienaventurados los pacificadores, porque ellos serán llamados hijos de Dios."},
    {"id": 267, "cat": "jesus", "cita": "Mateo 5:14", "libro": "Mateo", "texto": "Vosotros sois la luz del mundo; una ciudad asentada sobre un monte no se puede esconder."},
    {"id": 268, "cat": "jesus", "cita": "Mateo 5:16", "libro": "Mateo", "texto": "Así alumbre vuestra luz delante de los hombres, para que vean vuestras buenas obras, y glorifiquen a vuestro Padre que está en los cielos."},
    {"id": 269, "cat": "jesus", "cita": "Mateo 5:44", "libro": "Mateo", "texto": "Pero yo os digo: Amad a vuestros enemigos, bendecid a los que os maldicen, haced bien a los que os aborrecen, y orad por los que os ultrajan y os persiguen;"},
    {"id": 270, "cat": "jesus", "cita": "Mateo 6:33", "libro": "Mateo", "texto": "Mas buscad primeramente el reino de Dios y su justicia, y todas estas cosas os serán añadidas."},
    {"id": 271, "cat": "jesus", "cita": "Mateo 6:34", "libro": "Mateo", "texto": "Así que, no os afanéis por el día de mañana, porque el día de mañana traerá su afán. Basta a cada día su propio mal."},
    {"id": 272, "cat": "jesus", "cita": "Mateo 6:9", "libro": "Mateo", "texto": "Vosotros, pues, oraréis así: Padre nuestro que estás en los cielos, santificado sea tu nombre."},
    {"id": 273, "cat": "jesus", "cita": "Mateo 7:7", "libro": "Mateo", "texto": "Pedid, y se os dará; buscad, y hallaréis; llamad, y se os abrirá."},
    {"id": 274, "cat": "jesus", "cita": "Mateo 7:12", "libro": "Mateo", "texto": "Así que, todas las cosas que queráis que los hombres hagan con vosotros, así también haced vosotros con ellos; porque esto es la ley y los profetas."},
    {"id": 275, "cat": "jesus", "cita": "Mateo 11:28", "libro": "Mateo", "texto": "Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar."},
    {"id": 276, "cat": "jesus", "cita": "Mateo 11:29", "libro": "Mateo", "texto": "Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas;"},
    {"id": 277, "cat": "jesus", "cita": "Mateo 18:20", "libro": "Mateo", "texto": "Porque donde están dos o tres congregados en mi nombre, allí estoy yo en medio de ellos."},
    {"id": 278, "cat": "jesus", "cita": "Mateo 19:14", "libro": "Mateo", "texto": "Pero Jesús dijo: Dejad a los niños venir a mí, y no se lo impidáis; porque de los tales es el reino de los cielos."},
    {"id": 279, "cat": "jesus", "cita": "Mateo 22:37", "libro": "Mateo", "texto": "Jesús le dijo: Amarás al Señor tu Dios con todo tu corazón, y con toda tu alma, y con toda tu mente."},
    {"id": 280, "cat": "jesus", "cita": "Mateo 22:39", "libro": "Mateo", "texto": "Y el segundo es semejante: Amarás a tu prójimo como a ti mismo."},
    {"id": 281, "cat": "jesus", "cita": "Mateo 24:14", "libro": "Mateo", "texto": "Y será predicado este evangelio del reino en todo el mundo, para testimonio a todas las naciones; y entonces vendrá el fin."},
    {"id": 282, "cat": "jesus", "cita": "Mateo 24:44", "libro": "Mateo", "texto": "Por tanto, también vosotros estad preparados; porque el Hijo del Hombre vendrá a la hora que no pensáis."},
    {"id": 283, "cat": "jesus", "cita": "Mateo 24:35", "libro": "Mateo", "texto": "El cielo y la tierra pasarán, pero mis palabras no pasarán."},
    {"id": 284, "cat": "jesus", "cita": "Mateo 28:19", "libro": "Mateo", "texto": "Por tanto, id, y haced discípulos a todas las naciones, bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo;"},
    {"id": 285, "cat": "jesus", "cita": "Mateo 28:20", "libro": "Mateo", "texto": "enseñándoles que guarden todas las cosas que os he mandado; y he aquí yo estoy con vosotros todos los días, hasta el fin del mundo. Amén."},
    {"id": 286, "cat": "jesus", "cita": "Mateo 4:4", "libro": "Mateo", "texto": "Él respondió y dijo: Escrito está: No solo de pan vivirá el hombre, sino de toda palabra que sale de la boca de Dios."},
    {"id": 287, "cat": "jesus", "cita": "Mateo 25:40", "libro": "Mateo", "texto": "Y respondiendo el Rey, les dirá: De cierto os digo que en cuanto lo hicisteis a uno de estos mis hermanos más pequeños, a mí lo hicisteis."},
    {"id": 288, "cat": "jesus", "cita": "Marcos 2:27", "libro": "Marcos", "texto": "También les dijo: El día de reposo fue hecho por causa del hombre, y no el hombre por causa del día de reposo."},
    {"id": 289, "cat": "jesus", "cita": "Marcos 9:23", "libro": "Marcos", "texto": "Jesús le dijo: Si puedes creer, al que cree todo le es posible."},
    {"id": 290, "cat": "jesus", "cita": "Marcos 10:27", "libro": "Marcos", "texto": "Entonces Jesús, mirándolos, dijo: Para los hombres es imposible, mas para Dios, no; porque todas las cosas son posibles para Dios."},
    {"id": 291, "cat": "jesus", "cita": "Marcos 16:15", "libro": "Marcos", "texto": "Y les dijo: Id por todo el mundo y predicad el evangelio a toda criatura."},
    {"id": 292, "cat": "jesus", "cita": "Lucas 6:31", "libro": "Lucas", "texto": "Y como queréis que hagan los hombres con vosotros, así también haced vosotros con ellos."},
    {"id": 293, "cat": "jesus", "cita": "Lucas 6:38", "libro": "Lucas", "texto": "Dad, y se os dará; medida buena, apretada, remecida y rebosando darán en vuestro regazo; porque con la misma medida con que medís, os volverán a medir."},
    {"id": 294, "cat": "jesus", "cita": "Lucas 19:10", "libro": "Lucas", "texto": "Porque el Hijo del Hombre vino a buscar y a salvar lo que se había perdido."},
    {"id": 295, "cat": "jesus", "cita": "Lucas 15:10", "libro": "Lucas", "texto": "Así os digo que hay gozo delante de los ángeles de Dios por un pecador que se arrepiente."},
    {"id": 296, "cat": "jesus", "cita": "Apocalipsis 3:20", "libro": "Apocalipsis", "texto": "He aquí, yo estoy a la puerta y llamo; si alguno oye mi voz y abre la puerta, entraré a él, y cenaré con él, y él conmigo."},
    {"id": 297, "cat": "jesus", "cita": "Apocalipsis 22:12", "libro": "Apocalipsis", "texto": "He aquí yo vengo pronto, y mi galardón conmigo, para recompensar a cada uno según sea su obra."},
    {"id": 298, "cat": "jesus", "cita": "Apocalipsis 22:13", "libro": "Apocalipsis", "texto": "Yo soy el Alfa y la Omega, el principio y el fin, el primero y el último."},
    {"id": 299, "cat": "jesus", "cita": "Juan 4:14", "libro": "Juan", "texto": "mas el que bebiere del agua que yo le daré, no tendrá sed jamás; sino que el agua que yo le daré será en él una fuente de agua que salte para vida eterna."},
    {"id": 300, "cat": "jesus", "cita": "Mateo 24:42", "libro": "Mateo", "texto": "Velad, pues, porque no sabéis a qué hora ha de venir vuestro Señor."}
  ]
};
